class Provider implements CustomSource {
    api_key = "{{api-key}}"

    language = "en-US"
    include_adult = "false"

    getSettings(): Settings {
        return {
            supportsAnime: true,
            supportsManga: false,
        }
    }

    async getAnime(ids: number[]): Promise<$app.AL_BaseAnime[]> {
        const ret: $app.AL_BaseAnime[] = []
        const mediaCache = this._getMediaCache()

        for (const id of ids) {
            const cached = mediaCache[id]

            if (cached?.media) {
                ret.push(cached.media)
                continue
            }

            const decoded = this._decodeId(id)
            if (!decoded) continue

            const details = await this._getDetails(decoded.mediaType, decoded.tmdbId)
            if (!details) continue

            const stored = this._detailsToStoredMedia(decoded.mediaType, details)
            mediaCache[stored.media.id] = stored
            ret.push(stored.media)
        }

        this._setMediaCache(mediaCache)

        return ret
    }

    async getAnimeDetails(id: number): Promise<$app.AL_AnimeDetailsById_Media | null> {
        return null
    }

    async getAnimeMetadata(id: number): Promise<$app.Metadata_AnimeMetadata | null> {
        const mediaCache = this._getMediaCache()
        const cached = mediaCache[id]

        if (cached?.metadata) {
            return cached.metadata
        }

        const decoded = cached
            ? { mediaType: cached.mediaType, tmdbId: cached.tmdbId }
            : this._decodeId(id)

        if (!decoded) {
            return null
        }

        const details = await this._getDetails(decoded.mediaType, decoded.tmdbId)

        if (!details) {
            return null
        }

        const metadata = decoded.mediaType === "movie"
            ? this._movieDetailsToMetadata(details)
            : await this._tvDetailsToMetadata(details)

        const stored = cached || this._detailsToStoredMedia(decoded.mediaType, details)
        stored.metadata = metadata

        mediaCache[stored.media.id] = stored
        this._setMediaCache(mediaCache)

        return metadata
    }

    async getAnimeWithRelations(id: number): Promise<$app.AL_CompleteAnime> {
        const mediaCache = this._getMediaCache()
        let cached = mediaCache[id]

        if (!cached) {
            const media = await this.getAnime([id])
            if (!media || media.length === 0) {
                throw new Error("not found.")
            }

            cached = this._getMediaCache()[id]
        }

        if (!cached?.media) {
            throw new Error("not found.")
        }

        return {
            ...(cached.media as any),
            relations: { edges: [] },
        } as $app.AL_CompleteAnime
    }

    async listAnime(search: string, page: number, perPage: number): Promise<ListResponse<$app.AL_BaseAnime>> {
        const query = String(search || "").trim()
        const currentPage = page && page > 0 ? page : 1
        const limit = Math.max(1, Math.min(perPage || 20, 20))

        if (!this._hasApiKey()) {
            const media = [this._makeConfigRequiredCard()]
            return {
                media,
                total: media.length,
                page: 1,
                totalPages: 1,
            }
        }

        let response: TMDBListResponse<TMDBSearchItem> | null = null

        if (query.length > 0) {
            response = await this._tmdbGet<TMDBListResponse<TMDBSearchItem>>("/search/multi", {
                query,
                page: String(currentPage),
                include_adult: this._includeAdult() ? "true" : "false",
            })
        } else {
            response = await this._tmdbGet<TMDBListResponse<TMDBSearchItem>>("/trending/all/day", {
                page: String(currentPage),
            })
        }

        const results = (response?.results || [])
            .filter(item => item && (item.media_type === "movie" || item.media_type === "tv"))
            .slice(0, limit)

        const mediaCache = this._getMediaCache()
        const media: $app.AL_BaseAnime[] = []

        for (const item of results) {
            const stored = this._searchItemToStoredMedia(item)

            if (!stored) continue

            mediaCache[stored.media.id] = stored
            media.push(stored.media)
        }

        this._setMediaCache(mediaCache)

        return {
            media,
            total: response?.total_results || media.length,
            page: currentPage,
            totalPages: response?.total_pages || Math.max(1, Math.ceil(media.length / limit)),
        }
    }

    async getManga(ids: number[]): Promise<$app.AL_BaseManga[]> {
        return []
    }

    async getMangaDetails(id: number): Promise<$app.AL_MangaDetailsById_Media | null> {
        return null
    }

    async listManga(search: string, page: number, perPage: number): Promise<ListResponse<$app.AL_BaseManga>> {
        return {
            media: [],
            total: 0,
            page: 1,
            totalPages: 1,
        }
    }

    private async _getDetails(mediaType: TMDBMediaType, tmdbId: number): Promise<TMDBDetails | null> {
        if (!this._hasApiKey()) return null

        const path = mediaType === "movie"
            ? `/movie/${tmdbId}`
            : `/tv/${tmdbId}`

        return await this._tmdbGet<TMDBDetails>(path, {
            append_to_response: "videos,external_ids",
        })
    }

    private async _tmdbGet<T>(path: string, params?: Record<string, string>): Promise<T | null> {
        const key = this._apiKey()
        if (!key) return null

        const query: Record<string, string> = {
            api_key: key,
            language: this._language(),
            ...(params || {}),
        }

        const parts: string[] = []

        for (const k of Object.keys(query)) {
            const value = query[k]
            if (value === undefined || value === null || value === "") continue
            parts.push(`${encodeURIComponent(k)}=${encodeURIComponent(value)}`)
        }

        const url = `https://api.themoviedb.org/3${path}?${parts.join("&")}`

        try {
            const res = await fetch(url, {
                headers: {
                    "Accept": "application/json",
                    "Content-Type": "application/json",
                },
            })

            if (!res.ok) {
                const text = await res.text()
                console.error("TMDB error:", res.status, text)
                return null
            }

            return await res.json()
        } catch (err) {
            console.error("TMDB fetch failed:", err)
            return null
        }
    }

    private _searchItemToStoredMedia(item: TMDBSearchItem): StoredTMDBMedia | null {
        const mediaType = item.media_type

        if (mediaType !== "movie" && mediaType !== "tv") {
            return null
        }

        const tmdbId = Number(item.id)
        if (!tmdbId) return null

        const title = this._titleFromItem(item)
        const originalTitle = this._originalTitleFromItem(item)
        const dateStr = mediaType === "movie" ? item.release_date : item.first_air_date
        const date = this._parseDate(dateStr)
        const poster = this._poster(item.poster_path)
        const backdrop = this._backdrop(item.backdrop_path) || poster

        const media: $app.AL_BaseAnime = {
            id: this._encodeId(mediaType, tmdbId),
            siteUrl: this._siteUrl(mediaType, tmdbId),
            title: {
                userPreferred: title,
                romaji: title,
                english: title,
                native: originalTitle || title,
            },
            coverImage: {
                large: poster,
                medium: poster,
                extraLarge: poster,
                color: "",
            },
            bannerImage: backdrop,
            description: item.overview || "",
            genres: [mediaType === "movie" ? "Movie" : "TV", "TMDB"],
            meanScore: item.vote_average ? Math.round(item.vote_average * 10) : 0,
            synonyms: originalTitle && originalTitle !== title ? [originalTitle] : [],
            status: this._toStatus(undefined, dateStr),
            episodes: mediaType === "movie" ? 1 : 1,
            type: "ANIME",
            format: mediaType === "movie" ? "MOVIE" : "TV",
            seasonYear: date?.year || new Date().getUTCFullYear(),
            isAdult: !!item.adult,
            startDate: date || {
                year: new Date().getUTCFullYear(),
            },
            endDate: mediaType === "movie" ? date || undefined : undefined,
        }

        const metadata = this._fallbackMetadata(media, mediaType, item)

        return {
            tmdbId,
            mediaType,
            media,
            metadata,
        }
    }

    private _detailsToStoredMedia(mediaType: TMDBMediaType, details: TMDBDetails): StoredTMDBMedia {
        const tmdbId = Number(details.id)
        const title = mediaType === "movie"
            ? details.title || details.original_title || "Movie"
            : details.name || details.original_name || "TV Show"

        const originalTitle = mediaType === "movie"
            ? details.original_title || title
            : details.original_name || title

        const startDateStr = mediaType === "movie"
            ? details.release_date
            : details.first_air_date

        const endDateStr = mediaType === "movie"
            ? details.release_date
            : details.last_air_date

        const startDate = this._parseDate(startDateStr)
        const endDate = this._parseDate(endDateStr)

        const poster = this._poster(details.poster_path)
        const backdrop = this._backdrop(details.backdrop_path) || poster

        const genres = Array.isArray(details.genres)
            ? details.genres.map(g => g.name).filter(Boolean)
            : []

        if (!genres.includes("TMDB")) {
            genres.push("TMDB")
        }

        if (!genres.includes(mediaType === "movie" ? "Movie" : "TV")) {
            genres.push(mediaType === "movie" ? "Movie" : "TV")
        }

        let nextAiringEpisode: any = undefined

        if (mediaType === "tv" && details.next_episode_to_air?.air_date) {
            const airingAt = new Date(details.next_episode_to_air.air_date).getTime()

            if (!isNaN(airingAt)) {
                nextAiringEpisode = {
                    episode: details.next_episode_to_air.episode_number || 1,
                    airingAt,
                    timeUntilAiring: Math.floor((airingAt - Date.now()) / 1000),
                }
            }
        }

        const synonyms = [
            originalTitle,
            details.tagline || "",
            details.original_language || "",
        ].filter(x => x && x !== title)

        const media: $app.AL_BaseAnime = {
            id: this._encodeId(mediaType, tmdbId),
            siteUrl: this._siteUrl(mediaType, tmdbId),
            title: {
                userPreferred: title,
                romaji: title,
                english: title,
                native: originalTitle || title,
            },
            coverImage: {
                large: poster,
                medium: poster,
                extraLarge: poster,
                color: "",
            },
            bannerImage: backdrop,
            description: details.overview || "",
            genres,
            meanScore: details.vote_average ? Math.round(details.vote_average * 10) : 0,
            synonyms,
            status: this._toStatus(details.status, startDateStr),
            episodes: mediaType === "movie"
                ? 1
                : details.number_of_episodes || 1,
            type: "ANIME",
            format: mediaType === "movie" ? "MOVIE" : "TV",
            seasonYear: startDate?.year || new Date().getUTCFullYear(),
            isAdult: !!details.adult,
            startDate: startDate || {
                year: new Date().getUTCFullYear(),
            },
            endDate: endDate || undefined,
            nextAiringEpisode,
        }

        const metadata = mediaType === "movie"
            ? this._movieDetailsToMetadata(details)
            : this._fallbackMetadata(media, mediaType, details)

        return {
            tmdbId,
            mediaType,
            media,
            metadata,
        }
    }

    private _movieDetailsToMetadata(details: TMDBDetails): $app.Metadata_AnimeMetadata {
        const title = details.title || details.original_title || "Movie"
        const poster = this._poster(details.poster_path)
        const date = details.release_date || ""

        const description = this._truncate(
            [
                details.tagline || "",
                "",
                details.overview || "",
                "",
                `TMDB: ${this._siteUrl("movie", details.id)}`,
            ].filter(Boolean).join("\n"),
            4000,
        )

        return {
            titles: {
                en: title,
            },
            episodes: {
                "1": {
                    anidbId: 0,
                    tvdbId: 0,
                    anidbEid: 0,
                    title,
                    image: poster,
                    airDate: date,
                    length: details.runtime || 0,
                    summary: description,
                    overview: description,
                    episodeNumber: 1,
                    episode: "1",
                    seasonNumber: 1,
                    absoluteEpisodeNumber: 1,
                    hasImage: !!poster,
                },
            },
            episodeCount: 1,
            specialCount: 0,
        }
    }

    private async _tvDetailsToMetadata(details: TMDBDetails): Promise<$app.Metadata_AnimeMetadata> {
        const title = details.name || details.original_name || "TV Show"
        const tmdbId = Number(details.id)
        const seasons = Array.isArray(details.seasons)
            ? details.seasons
                .filter(s => Number(s.season_number) > 0)
                .sort((a, b) => Number(a.season_number) - Number(b.season_number))
            : []

        const episodes: Record<string, $app.Metadata_EpisodeMetadata> = {}
        let absoluteEpisodeNumber = 1

        const fallbackRuntime = Array.isArray(details.episode_run_time) && details.episode_run_time.length > 0
            ? details.episode_run_time[0]
            : 0

        for (const season of seasons) {
            const seasonNumber = Number(season.season_number)
            const seasonDetails = await this._tmdbGet<TMDBSeasonDetails>(
                `/tv/${tmdbId}/season/${seasonNumber}`,
                {},
            )

            const seasonEpisodes = Array.isArray(seasonDetails?.episodes)
                ? seasonDetails!.episodes
                : []

            if (seasonEpisodes.length === 0 && season.episode_count) {
                for (let i = 1; i <= season.episode_count; i++) {
                    const key = String(absoluteEpisodeNumber)
                    episodes[key] = {
                        anidbId: 0,
                        tvdbId: 0,
                        anidbEid: 0,
                        title: `Episode ${i}`,
                        image: this._poster(season.poster_path),
                        airDate: "",
                        length: fallbackRuntime,
                        summary: "",
                        overview: "",
                        episodeNumber: absoluteEpisodeNumber,
                        episode: String(absoluteEpisodeNumber),
                        seasonNumber,
                        absoluteEpisodeNumber,
                        hasImage: !!season.poster_path,
                    }
                    absoluteEpisodeNumber++
                }

                continue
            }

            for (const ep of seasonEpisodes) {
                const image = this._still(ep.still_path)
                const epTitle = ep.name || `Episode ${ep.episode_number || absoluteEpisodeNumber}`
                const summary = ep.overview || ""

                const key = String(absoluteEpisodeNumber)
                episodes[key] = {
                    anidbId: 0,
                    tvdbId: 0,
                    anidbEid: 0,
                    title: epTitle,
                    image,
                    airDate: ep.air_date || "",
                    length: ep.runtime || fallbackRuntime || 0,
                    summary,
                    overview: summary,
                    episodeNumber: absoluteEpisodeNumber,
                    episode: String(absoluteEpisodeNumber),
                    seasonNumber,
                    absoluteEpisodeNumber,
                    hasImage: !!image,
                }

                absoluteEpisodeNumber++
            }
        }

        if (Object.keys(episodes).length === 0) {
            const poster = this._poster(details.poster_path)
            const description = this._truncate(details.overview || "", 4000)

            episodes["1"] = {
                anidbId: 0,
                tvdbId: 0,
                anidbEid: 0,
                title,
                image: poster,
                airDate: details.first_air_date || "",
                length: fallbackRuntime,
                summary: description,
                overview: description,
                episodeNumber: 1,
                episode: "1",
                seasonNumber: 1,
                absoluteEpisodeNumber: 1,
                hasImage: !!poster,
            }
        }

        const specialSeason = Array.isArray(details.seasons)
            ? details.seasons.find(s => Number(s.season_number) === 0)
            : undefined

        return {
            titles: {
                en: title,
            },
            episodes,
            episodeCount: Object.keys(episodes).length,
            specialCount: specialSeason?.episode_count || 0,
        }
    }

    private _fallbackMetadata(media: $app.AL_BaseAnime, mediaType: TMDBMediaType, source: any): $app.Metadata_AnimeMetadata {
        const title = media.title?.english || media.title?.romaji || media.title?.userPreferred || "TMDB Title"
        const image = media.coverImage?.large || ""
        const date = media.startDate?.year
            ? `${media.startDate.year}-${this._pad(media.startDate.month || 1)}-${this._pad(media.startDate.day || 1)}`
            : ""

        const description = this._truncate(media.description || source?.overview || "", 4000)

        return {
            titles: {
                en: title,
            },
            episodes: {
                "1": {
                    anidbId: 0,
                    tvdbId: 0,
                    anidbEid: 0,
                    title,
                    image,
                    airDate: date,
                    length: mediaType === "movie" ? source?.runtime || 0 : 0,
                    summary: description,
                    overview: description,
                    episodeNumber: 1,
                    episode: "1",
                    seasonNumber: 1,
                    absoluteEpisodeNumber: 1,
                    hasImage: !!image,
                },
            },
            episodeCount: mediaType === "movie" ? 1 : media.episodes || 1,
            specialCount: 0,
        }
    }

    private _makeConfigRequiredCard(): $app.AL_BaseAnime {
        const title = "TMDB API key required"
        const now = new Date()

        return {
            id: 999999001,
            siteUrl: "https://www.themoviedb.org/settings/api",
            title: {
                userPreferred: title,
                romaji: title,
                english: title,
                native: title,
            },
            coverImage: {
                large: "",
                medium: "",
                extraLarge: "",
                color: "",
            },
            bannerImage: "",
            description: "Add your TMDB v3 API key in this extension's settings.",
            genres: ["TMDB"],
            meanScore: 0,
            synonyms: [],
            status: "FINISHED",
            episodes: 1,
            type: "ANIME",
            format: "TV",
            seasonYear: now.getUTCFullYear(),
            isAdult: false,
            startDate: {
                year: now.getUTCFullYear(),
                month: now.getUTCMonth() + 1,
                day: now.getUTCDate(),
            },
            endDate: undefined,
        }
    }

    private _encodeId(mediaType: TMDBMediaType, tmdbId: number): number {
        if (mediaType === "movie") {
            return 1000000000 + Number(tmdbId)
        }

        return 2000000000 + Number(tmdbId)
    }

    private _decodeId(id: number): { mediaType: TMDBMediaType, tmdbId: number } | null {
        const numericId = Number(id)

        if (!numericId || isNaN(numericId)) {
            return null
        }

        if (numericId >= 2000000000) {
            return {
                mediaType: "tv",
                tmdbId: numericId - 2000000000,
            }
        }

        if (numericId >= 1000000000) {
            return {
                mediaType: "movie",
                tmdbId: numericId - 1000000000,
            }
        }

        return null
    }

    private _titleFromItem(item: TMDBSearchItem): string {
        return item.title || item.name || item.original_title || item.original_name || "TMDB Title"
    }

    private _originalTitleFromItem(item: TMDBSearchItem): string {
        return item.original_title || item.original_name || this._titleFromItem(item)
    }

    private _siteUrl(mediaType: TMDBMediaType, tmdbId: number): string {
        return mediaType === "movie"
            ? `https://www.themoviedb.org/movie/${tmdbId}`
            : `https://www.themoviedb.org/tv/${tmdbId}`
    }

    private _poster(path?: string): string {
        if (!path) return ""
        if (path.startsWith("http")) return path
        return `https://image.tmdb.org/t/p/w500${path}`
    }

    private _backdrop(path?: string): string {
        if (!path) return ""
        if (path.startsWith("http")) return path
        return `https://image.tmdb.org/t/p/w1280${path}`
    }

    private _still(path?: string): string {
        if (!path) return ""
        if (path.startsWith("http")) return path
        return `https://image.tmdb.org/t/p/w500${path}`
    }

    private _parseDate(dateStr?: string): { year: number, month?: number, day?: number } | null {
        if (!dateStr) return null

        const d = new Date(dateStr)

        if (isNaN(d.getTime())) {
            return null
        }

        return {
            year: d.getUTCFullYear(),
            month: d.getUTCMonth() + 1,
            day: d.getUTCDate(),
        }
    }

    private _toStatus(status?: string, firstDate?: string): string {
        const first = firstDate ? new Date(firstDate).getTime() : 0

        if (first && !isNaN(first) && first > Date.now()) {
            return "NOT_YET_RELEASED"
        }

        const s = String(status || "").toLowerCase()

        if (
            s.includes("returning") ||
            s.includes("in production")
        ) {
            return "RELEASING"
        }

        if (
            s.includes("planned") ||
            s.includes("pilot") ||
            s.includes("post production") ||
            s.includes("rumored")
        ) {
            return "NOT_YET_RELEASED"
        }

        return "FINISHED"
    }

    private _apiKey(): string {
        const key = String(this.api_key || "").trim()

        if (!key || key.includes("{{") || key.includes("}}")) {
            return ""
        }

        return key
    }

    private _hasApiKey(): boolean {
        return this._apiKey().length > 0
    }

    private _language(): string {
        const lang = String(this.language || "en-US").trim()

        if (!lang || lang.includes("{{") || lang.includes("}}")) {
            return "en-US"
        }

        return lang
    }

    private _includeAdult(): boolean {
        const value = String(this.include_adult || "false").toLowerCase().trim()
        return value === "true" || value === "1" || value === "yes"
    }

    private _truncate(input: string, max: number): string {
        if (!input) return ""
        if (input.length <= max) return input
        return input.slice(0, max - 3) + "..."
    }

    private _pad(value: number): string {
        return value < 10 ? `0${value}` : `${value}`
    }

    private _getMediaCache(): Record<number, StoredTMDBMedia> {
        return ($store.get("tmdb.media") as Record<number, StoredTMDBMedia> | undefined) || {}
    }

    private _setMediaCache(cache: Record<number, StoredTMDBMedia>) {
        $store.set("tmdb.media", cache)
    }
}

type TMDBMediaType = "movie" | "tv"

type StoredTMDBMedia = {
    tmdbId: number
    mediaType: TMDBMediaType
    media: $app.AL_BaseAnime
    metadata?: $app.Metadata_AnimeMetadata
}

type TMDBListResponse<T> = {
    page: number
    results: T[]
    total_pages: number
    total_results: number
}

type TMDBGenre = {
    id: number
    name: string
}

type TMDBSearchItem = {
    id: number
    media_type: "movie" | "tv" | "person" | string
    title?: string
    name?: string
    original_title?: string
    original_name?: string
    overview?: string
    poster_path?: string
    backdrop_path?: string
    release_date?: string
    first_air_date?: string
    vote_average?: number
    vote_count?: number
    popularity?: number
    adult?: boolean
    genre_ids?: number[]
    original_language?: string
}

type TMDBDetails = {
    id: number

    title?: string
    original_title?: string
    name?: string
    original_name?: string

    overview?: string
    tagline?: string
    status?: string

    poster_path?: string
    backdrop_path?: string

    release_date?: string
    first_air_date?: string
    last_air_date?: string

    runtime?: number
    episode_run_time?: number[]

    vote_average?: number
    vote_count?: number
    popularity?: number

    adult?: boolean
    original_language?: string

    genres?: TMDBGenre[]

    number_of_episodes?: number
    number_of_seasons?: number
    seasons?: TMDBSeason[]

    next_episode_to_air?: TMDBEpisode
}

type TMDBSeason = {
    id?: number
    name?: string
    overview?: string
    poster_path?: string
    season_number: number
    episode_count?: number
    air_date?: string
}

type TMDBSeasonDetails = {
    id: number
    name?: string
    overview?: string
    poster_path?: string
    season_number: number
    air_date?: string
    episodes?: TMDBEpisode[]
}

type TMDBEpisode = {
    id?: number
    name?: string
    overview?: string
    air_date?: string
    episode_number?: number
    season_number?: number
    still_path?: string
    runtime?: number
}
